import{_ as t,o,c as p,a5 as a}from"./chunks/framework.DJo0M80U.js";const v=JSON.parse('{"title":"神奇 这款 Vue 后台框架居然不用手动配置路由","description":"Alinmei 于 2022 03 04 17:26:09 发布 2621 收藏 6 分类专栏： 前端技术 文章标签： java 前端 版权 前端技术 专栏收录该内容 6 篇文章0 订阅 订阅专栏 前言 做 Vue 开发脱离不了路由，尤其是中大型项目，页面多且杂，在配置路由的时候。","frontmatter":{"title":"神奇 这款 Vue 后台框架居然不用手动配置路由","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"Alinmei 于 2022 03 04 17:26:09 发布 2621 收藏 6 分类专栏： 前端技术 文章标签： java 前端 版权 前端技术 专栏收录该内容 6 篇文章0 订阅 订阅专栏 前言 做 Vue 开发脱离不了路由，尤其是中大型项目，页面多且杂，在配置路由的时候。","sidebarWeight":53,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vueRouter/神奇 这款 Vue 后台框架居然不用手动配置路由.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/神奇 这款 Vue 后台框架居然不用手动配置路由.md","filePath":"posts/Vue系统教程/04-路由与状态管理/神奇 这款 Vue 后台框架居然不用手动配置路由.md"}'),u={name:"posts/Vue系统教程/04-路由与状态管理/神奇 这款 Vue 后台框架居然不用手动配置路由.md"};function r(s,e,i,l,n,g){return o(),p("div",null,[...e[0]||(e[0]=[a('<div><h1 id="神奇-这款-vue-后台框架居然不用手动配置路由" tabindex="-1">神奇 这款 Vue 后台框架居然不用手动配置路由 <a class="header-anchor" href="#神奇-这款-vue-后台框架居然不用手动配置路由" aria-label="Permalink to &quot;神奇 这款 Vue 后台框架居然不用手动配置路由&quot;">​</a></h1><blockquote><p>本节目标：理解“神奇 这款 Vue 后台框架居然不用手动配置路由”的核心思路，并能把它用于实际开发或面试表达。 Alinmei</p></blockquote><p>于 2022-03-04 17:26:09 发布</p><p>2621 收藏 6 分类专栏： 前端技术 文章标签： java 前端 版权</p><p>前端技术 专栏收录该内容 6 篇文章0 订阅 订阅专栏 前言 做 Vue 开发脱离不了路由，尤其是中大型项目，页面多且杂，在配置路由的时候总是会变得逐渐暴躁，因为费时，并且又没有什么太多技术含量，总觉得是在浪费时间。</p><p>另外如果接手了别人的项目，当业务有变更，或者测试反馈有 bug 。通常需要先要根据页面 URL 去找到对应配置的路由，然后对照 component 参数对应的 .vue 文件，操作繁琐，效率也不高。</p><p>那有没有一种办法可以根据 .vue 文件自动生成路由，并且路由的 path 就是文件所在的文件夹路径，这样即节省了路由配置的时间，也提高了根据 URL 定位页面文件的效率。</p><p>经过我的一番查找，还真找到了，就是下面这两个插件：</p><p>vite-plugin-pages vite-plugin-vue-layouts 使用 安装 从这两款插件的名字可以看出，这俩是 vite 的插件，并且仅支持 Vue3 ，那我就搬出我的 Fantastic-template 项目模版拿来测试了。</p><p>首先先安装依赖。因为模版里自带了 vue-router ，所以不需要再安装。</p><p>pnpm add vite-plugin-pages vite-plugin-vue-layouts -D 安装好依赖后，需要在 vite.config.js 里进行配置，由于这两个插件作用不同，我们一个个来介绍如何使用。</p><p>vite-plugin-pages 这个是本次介绍的核心，它能够将文件系统生成对应的路由，从而省去手动配置路由的时间。</p><p>首先在 vite.config.js 增加以下配置：</p><p>import Pages from &#39;vite-plugin-pages&#39; export default { plugins: [ Pages({ dirs: &#39;src/views&#39;, // 需要生成路由的文件目录 exclude: [&#39;**/components/*.vue&#39;] // 排除在外的目录，即不将所有 components 目录下的 .vue 文件生成路由 }) ] } 目前只需要配置这 2 个参数就够了，其它还有更多参数可以去 vite-plugin-pages 项目页了解。</p><p>接着在页面中引入就可以使用了。</p><p>import { createRouter } from &#39;vue-router&#39; import routes from &#39;~pages&#39; const router = createRouter({ // ... routes }) 没错，就是这么简单，当然也有一些高阶用法。比如通过 params 传参的路由，要怎么配置呢？</p><p>在 vite-plugin-pages 里提供了一种专用的写法，就是 [ ] 。例如 src/views/example/[id].vue 这个文件，最终生成的路由 path 就是 /example/:id 。</p><p>针对 404 页面，我们可以在创建个这样的文件 src/views/[...all].vue ，它生成的路由就是 /:all(.<em>)</em> 。</p><p>除此之外，我们还可以在 .vue 文件中增加 &lt;route&gt;&lt;/route&gt; 代码块，这里面默认接收 json5 格式的路由配置。需要注意的是，如果在 &lt;route&gt;&lt;/route&gt; 里配置了 path 和 name ，将会覆盖自动生成的 path 和 name 。</p><p>&lt;route&gt; { path: &#39;/xxx/yyy&#39;, name: &#39;zzz&#39;, meta: { title: &#39;test page&#39; } } &lt;/route&gt; &lt;template&gt; &lt;div&gt; This is a test page. &lt;/div&gt; &lt;/template&gt; 这时候似乎还缺点什么，对的，那就是嵌套路由。通过 vite-plugin-pages 自动生成的路由，都是一级路由。而实际项目开发中，我们会使用嵌套路由的特性，搭配 &lt;router-view&gt;&lt;/router-view&gt; 组件实现一些布局效果。</p><p>这时候就要介绍下面这款插件了</p><p>vite-plugin-vue-layouts 首先在 vite.config.js 修改下配置：</p><p>import Pages from &#39;vite-plugin-pages&#39; import Layouts from &#39;vite-plugin-vue-layouts&#39; export default { plugins: [ Pages({ dirs: &#39;src/views&#39;, // 需要生成路由的文件目录 exclude: [&#39;**/components/*.vue&#39;] // 排除在外的目录，即所有 components 目录下的 .vue 文件都不会生成路由 }), Layouts({ layoutsDirs: &#39;src/layout&#39;, // 布局文件存放目录 defaultLayout: &#39;index&#39; // 默认布局，对应 src/layout/index.vue }) ] } 更多配置参数请查看 vite-plugin-vue-layouts 项目页。</p><p>也还是一样，配置好后，就可以直接使用了。</p><p>import { createRouter } from &#39;vue-router&#39; import { setupLayouts } from &#39;virtual:generated-layouts&#39; import generatedRoutes from &#39;virtual:generated-pages&#39; const routes = setupLayouts(generatedRoutes) const router = createRouter({ // ... routes }) 这个插件只做一件事，就是把通过 vite-plugin-pages 生成的一级路由处理成嵌套路由，大概就是这样：</p><p>// 处理前 { path: &#39;/login&#39;, component: () =&gt; import(&#39;/src/views/login.vue&#39;), name: &#39;login&#39; } // 处理后 { path: &#39;/login&#39;, component: () =&gt; import(&#39;/src/layout/index.vue&#39;), children: [ { path: &#39;&#39;, component: () =&gt; import(&#39;/src/views/login.vue&#39;), name: &#39;login&#39; } ] } 如果你有多种布局，可以在 &lt;route&gt;&lt;route&gt; 里进行设置：</p><p>&lt;route&gt; { meta: { layout: &#39;other&#39; } } &lt;/route&gt; 甚至还可以做一些魔改，比如项目中有的路由是需要用到布局页面的，有的则不需要，那我们可以将不需要的页面设置为 layout: false ：</p><p>&lt;route&gt; { meta: { layout: false } } &lt;/route&gt; 同时在路由文件处使用下面这段代码：</p><p>import { createRouter } from &#39;vue-router&#39; import { setupLayouts } from &#39;virtual:generated-layouts&#39; import generatedRoutes from &#39;virtual:generated-pages&#39; let routes = [] generatedRoutes.forEach(v =&gt; { routes.push(v?.meta?.layout != false ? setupLayouts([v])[0] : v) }) const router = createRouter({ // ... routes }) 总结通过下面这张图配合总结吧：</p><p>使用路由参数需通过 [ ] 将参数名包裹，并设为文件名 文件夹不会生成路由，例如 example 文件夹并没有生成 /example 路由 路由 name 会根据文件的目录结构自动生成，并用 - 连接，可确保 name 的唯一性 所有 components 目录均不会生成路由 ———————————————— 版权声明：本文为CSDN博主「Alinmei」的原创文章，遵循CC 4.0 BY-SA版权协议，转载请附上原文出处链接及本声明。 原文链接：<a href="https://blog.csdn.net/Alinmei/article/details/123281288" target="_blank" rel="noreferrer">https://blog.csdn.net/Alinmei/article/details/123281288</a></p></div>',1)])])}const c=t(u,[["render",r]]);export{v as __pageData,c as default};
